int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    while (n--) {
        string s;
        cin >> s;
        int count = 0;
        int max_len = 0;
        int start = -1;
        bool in = false;

        for (int i = 0; i < (int)s.length(); i++) {
            if (s[i] == '_') {
                if (start != i - 1) {
                    if (in)
                        count++;
                    else
                        max_len = max(max_len, i - 1 - start);
                }
                start = i;
            }
            else if (s[i] == '(') {
                in = true;
                if (start != i - 1)
                    max_len = max(max_len, i - 1 - start);
                start = i;
            }
            else if (s[i] == ')') {
                in = false;
                if (start != i - 1)
                    count++;
                start = i;
            }
        }
        if (start != (int)s.length() - 1)
            max_len = max(max_len, (int)s.length() - 1 - start);
        cout << max_len << " " << count << "\n";
    }

    return 0;
}
